	user_set_db(b, -12.0f);
	WAIT_FOR(nreports_now() > n);
	fprintf(stderr, "  reports after the Mac move: %u (was %u) last: %s\n", nreports_now(), n, last_report());
	CHECK(nreports_now() > n, "the Mac move on the new ID never reached LMS");
	stop();
}

